item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic [99:0] in,
    output wire  [99:0] out
);
    genvar i;
    generate
        for (i = 0; i < 100; i = i + 1) begin : reverse_bits
            assign out[i] = in[99-i];
        end
    endgenerate
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
module dev_tb;
    logic [99:0] in;
    wire [99:0] out;
    logic [99:0] expected;
    integer tests = 0;
    TopModule dut (.in(in), .out(out));

    task automatic check(input logic [99:0] value);
        in = value;
        for (integer j = 0; j < 100; j = j + 1)
            expected[99-j] = value[j];
        #1;
        if (out "'!== expected)
            $fatal(1, "FAIL input=%h expected=%h actual=%h", in, expected, out);
        tests = tests + 1;
    endtask

    initial begin
        check('"'0);
        check('1);
        for (integer k = 0; k < 100; k = k + 1) begin
            check(100'b1 << k);
            check(~(100'b1 << k));
        end
        for (integer k = 0; k < 1000; k = k + 1)
            check({"'$urandom, $urandom, $urandom, $urandom});
        check({50{2'"'b10}});
        check({50{2'b01}});
        check('x);
        check('z);
        "'$display("PASS: %0d bit-reversal checks", tests);
        $finish;
    end
    initial begin
        #2000;
        $fatal(1, "FAIL timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
compile_status=$?
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > simulation.log 2>&1
    simulation_status=$?
else
    simulation_status=not_run
fi
printf '"'compile_exit=%s\\nsimulation_exit=%s\\n' \""'$compile_status" "$simulation_status" > check_status.log
cat check_status.log compile.log simulation.log'

